 // ── HH:MM برای شیت ورود داده (بدون نیاز به تغییر index.html) ──\n  (function pspHmDataEntryPatch() {\n    function hoursToHM(hours) {\n      var mins = Math.round((Number(hours) || 0) * 60);\n      if (mins < 0) mins = 0;\n      var h = Math.floor(mins / 60), m = mins % 60;\n      return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;\n    }\n    function parseHMtoHours(str) {\n      str = String(str || '').trim();\n      if (!str) return 0;\n      if (/^\\d+(\\.\\d+)?$/.test(str) && str.indexOf(':') < 0) return Number(str) || 0;\n      var s = str.replace(/[^0-9:]/g, '');\n      if (/^\\d{3,4}$/.test(s)) {\n        while (s.length < 4) s = '0' + s;\n        return (parseInt(s.slice(0, 2), 10) || 0) + (parseInt(s.slice(2, 4), 10) || 0) / 60;\n      }\n      var p = s.split(':');\n      return (parseInt(p[0], 10) || 0) + (parseInt(p[1] || '0', 10) || 0) / 60;\n    }\n    window.hoursToHM = window.hoursToHM || hoursToHM;\n    window.parseHMtoHours = window.parseHMtoHours || parseHMtoHours;\n\n    function isHourHeader(t) {\n      t = String(t || '').replace(/\\s+/g, ' ').trim();\n      if (!t) return false;\n      // هرگز ستون‌های تعداد / اقماری را ساعت نگیر\n      if (t.indexOf('اقمار') >= 0) return false;\n      if (t.indexOf('تعداد') >= 0) return false;\n      if (/مرخصی\\s*ساعتی|ساعت\\s*مرخصی/.test(t)) return true;\n      if (/ساعت\\s*مأم?وریت|مأم?وریت\\s*ساعتی/.test(t)) return true;\n      if (/ساعات\\s*اضافه|ساعت\\s*اضافه|^اضافه‌?کار$/.test(t)) return true;\n      if (/ساعات\\s*شب|ساعت\\s*شب|^شب‌?کاری$/.test(t)) return true;\n      if (/کسری|غیبت\\s*ساعت/.test(t)) return true;\n      return false;\n    }\n    function fieldFromHourHeader(header) {\n      var t = String(header || '');\n      if (t.indexOf('اقمار') >= 0 || t.indexOf('تعداد') >= 0) return null;\n      if (/مرخصی\\s*ساعتی|ساعت\\s*مرخصی/.test(t)) return 'hourlyLeave';\n      if (/ساعت\\s*مأم?وریت|مأم?وریت\\s*ساعتی/.test(t)) return 'missionHours';\n      if (/ساعات\\s*اضافه|ساعت\\s*اضافه|^