function isPlainObject(x) {
  return x !== null && typeof x === 'object' && !Array.isArray(x);
}
function arrOf(x) { return Array.isArray(x) ? x : []; }
function objOf(x) { return isPlainObject(x) ? x : {}; }
function isInt(x, lo, hi) { return Number.isInteger(x) && x >= lo && x <= hi; }
function isNum(x) { return typeof x === 'number' && Number.isFinite(x); }

async function readBody(request) {
  const m = request.method;
  if (m !== 'POST' && m !== 'PUT' && m !== 'DELETE' && m !== 'PATCH') {
    return { error: jsonResponse({ ok: false, error: 'method_not_allowed' }, 405) };
  }
  const site = request.headers.get('Sec-Fetch-Site');
  if (site && site !== 'same-origin') return { error: jsonResponse({ ok: false, error: 'forbidden' }, 403) };
  if (Number(request.headers.get('Content-Length') || 0) > MAX_BODY_BYTES) {
    return { error: jsonResponse({ ok: false, error: 'too_large' }, 413) };
  }
  try {
    const text = await request.text();
    if (text.length > MAX_BODY_BYTES) return { error: jsonResponse({ ok: false, error: 'too_large' }, 413) };
    const body = JSON.parse(text);
    if (!isPlainObject(body)) return { error: jsonResponse({ ok: false, error: 'bad_request' }, 400) };
    return { body: body };
  } catch (e) {
    return { error: jsonResponse({ ok: false, error: 'bad_json' }, 400) };
  }
}

// ---------- Supabase helpers ----------
function storeConfig(env) {
  const url = String(env.SUPABASE_URL || '').trim().replace(/\/+$/, '');
  const key = String(env.SUPABASE_SERVICE_KEY || '').trim();
  if (!/^https:\/\/[A-Za-z0-9.-]+$/.test(url) || !key) return null;
  return { url: url, key: key };
}

function storeHeaders(cfg, extra) {
  const h = { apikey: cfg.key };
  if (/^eyJ/.test(cfg.key)) h.Authorization = 'Bearer ' + cfg.key;
  return Object.assign(h, extra || {});
}

async function storeFail(r) {
  let code = '';
  try { code = String(JSON.parse((await r.text()).slice(0, 2000)).code || ''); } catch (e) {}
  let reason = 'store_error';
  if (r.status === 404 || code === 'PGRST205' || code === '42P01') reason = 'table_missing';
  else if (r.status === 401 || r.status === 403 || code === '42501') reason = 'bad_key';
  return { reason: reason, status: r.status };
}

function storeFailResponse(f) {
  return jsonResponse({ ok: false, error: 'store_error', reason: f.reason, upstream: f.status }, 502);
}

async function storeVersions(cfg) {
  const r = await fetch(cfg.url + '/rest/v1/app_docs?select=name,version', { headers: storeHeaders(cfg) });
  if (!r.ok) return { fail: await storeFail(r) };
  const rows = await r.json();
  const v = { settings: 0, data: 0, log: 0 };
  rows.forEach(function (x) { if (x && STATE_DOCS.indexOf(x.name) >= 0) v[x.name] = Number(x.version) || 0; });
  return { versions: v };
}

async function storeGetData(cfg) {
  const r = await fetch(cfg.url + '/rest/v1/app_docs?name=eq.data&select=version,data',
    { headers: storeHeaders(cfg, { Accept: 'application/vnd.pgrst.object+json' }) });
  if (r.status === 406) return { version: 0, obj: null };
  if (!r.ok) return { fail: await storeFail(r) };
  const row = await r.json();
  let obj = null;
  if (row && row.data) {
    try { obj = JSON.parse(row.data); } catch (e) { return { fail: { reason: 'bad_json', status: 502 } }; }
  }
  if (obj) {
    try { mergeAllEmployeeExtras(obj); } catch (eMerge) { /* non-fatal */ }
    try { await storeMergeSettingsIntoDataObj(cfg, obj); } catch (eSM) { /* non-fatal */ }
    // ترمیم شناوری: فقط portal/settings — هرگز max تقویم‌ها (که ۹۰ را برمی‌گرداند)
    try {
      if (obj.settings && typeof obj.settings === 'object') {
        var fm = parseFloatMinutesValue(obj.settings.portalFloatMinutes, null);
        if (fm == null) fm = parseFloatMinutesValue(obj.settings.floatMinutes, null);
        if (fm == null) {
          var nc = obj.settings.contractCalendars && obj.settings.contractCalendars.normal;
          fm = parseFloatMinutesValue(nc && nc.floatMinutes, null);
        }
        if (fm != null) {
          obj.settings.portalFloatMinutes = fm;
          obj.settings.floatMinutes = fm;
          Object.keys(obj.settings.contractCalendars || {}).forEach(function (id) {
            if (String(id) === 'hourly') return;
            var c = obj.settings.contractCalendars[id];
            if (c && typeof c === 'object') c.floatMinutes = fm;
          });
        }
      }
    } catch (eFloatHeal) {}
  }
  return { version: Number(row.version) || 0, obj: obj };
}


/** سند «settings» (ثابت‌های ماهانه، قوانین کسر، برچسب‌ها) جدا از سند «data» ذخیره می‌شود */
async function storeGetSettingsDoc(cfg) {
  try {
    const r = await fetch(cfg.url + '/rest/v1/app_docs?name=eq.settings&select=version,data',
      { headers: storeHeaders(cfg, { Accept: 'application/vnd.pgrst.object+json' }) });
    if (!r.ok) return null;
    const row = await r.json();
    if (!row || !row.data) return null;
    const o = (typeof row.data === 'string') ? JSON.parse(row.data) : row.data;
    return (o && typeof o === 'object') ? o : null;
  } catch (e) { return null; }
}

/** خواندن سند settings با version برای ذخیره */
async function storeGetSettingsDocFull(cfg) {
  try {
    const r = await fetch(cfg.url + '/rest/v1/app_docs?name=eq.settings&select=version,data',
      { headers: storeHeaders(cfg, { Accept: 'application/vnd.pgrst.object+json' }) });
    if (r.status === 406) return { version: 0, obj: {} };
    if (!r.ok) return { fail: await storeFail(r) };
    const row = await r.json();
    let obj = {};
    if (row && row.data) {
      try { obj = (typeof row.data === 'string') ? JSON.parse(row.data) : row.data; } catch (e) { obj = {}; }
    }
    if (!obj || typeof obj !== 'object') obj = {};
    return { version: Number(row.version) || 0, obj: obj };
  } catch (e) { return { fail: { reason: 'settings_get', message: String(e && e.message || e) } }; }
}

async function storePutSettingsDoc(cfg, baseVersion, obj) {
  try {
    const ver = Number(baseVersion) || 0;
    const payload = JSON.stringify({
      version: ver + 1,
      data: JSON.stringify(obj || {}),
      updated_at: new Date().toISOString()
    });
    // اطمینان از وجود ردیف
    if (ver === 0) {
      await fetch(cfg.url + '/rest/v1/app_docs?on_conflict=name', {
        method: 'POST',
        headers: storeHeaders(cfg, { 'Content-Type': 'application/json', Prefer: 'resolution=ignore-duplicates,return=minimal' }),
        body: JSON.stringify([{ name: 'settings', version: 0, data: '{}' }])
      });
    }
    let r = await fetch(cfg.url + '/rest/v1/app_docs?name=eq.settings&version=eq.' + ver + '&select=version', {
      method: 'PATCH',
      headers: storeHeaders(cfg, { 'Content-Type': 'application/json', Prefer: 'return=representation' }),
      body: payload
    });
    if (r.status === 409 || r.status === 412) return { conflict: true };
    if (!r.ok) {
      // بدون شرط version یک‌بار دیگر
      r = await fetch(cfg.url + '/rest/v1/app_docs?name=eq.settings', {
        method: 'PATCH',
        headers: storeHeaders(cfg, { 'Content-Type': 'application/json', Prefer: 'return=representation' }),
        body: payload
      });
      if (!r.ok) {
        const r2 = await fetch(cfg.url + '/rest/v1/app_docs', {
          method: 'POST',
          headers: storeHeaders(cfg, { 'Content-Type': 'application/json', Prefer: 'return=minimal' }),
          body: JSON.stringify({ name: 'settings', version: 1, data: JSON.stringify(obj || {}), updated_at: new Date().toISOString() })
        });
        if (!r2.ok) return { fail: await storeFail(r2) };
        return { ok: true, version: 1 };
      }
    }
    return { ok: true, version: ver + 1 };
  } catch (e) { return { fail: { reason: 'settings_put', message: String(e && e.message || e) } }; }
}

/** data سند کارکنان است؛ leavePolicy و سیاست‌ها در سند settings هستند — باید ادغام شوند */

/** همگام‌سازی پایدار تنظیمات پورتال به سند settings */
async function syncPortalPolicyToSettingsDoc(cfg, dataObj) {
  try {
    if (!cfg || !dataObj || !dataObj.settings) return;
    const gs = await storeGetSettingsDocFull(cfg);
    if (gs.fail) return;
    const sObj = gs.obj || {};
    const s = dataObj.settings;
    if (s.leavePolicy && typeof s.leavePolicy === 'object') {
      sObj.leavePolicy = JSON.parse(JSON.stringify(s.leavePolicy));
    }
    if (s.requestGraceDays != null && s.requestGraceDays !== '') {
      sObj.requestGraceDays = s.requestGraceDays;
    }
    if (s.monthlyShortfallAllowanceHours != null && s.monthlyShortfallAllowanceHours !== '') {
      var n = Number(s.monthlyShortfallAllowanceHours);
      sObj.monthlyShortfallAllowanceHours = n;
      sObj.shortfallAllowanceHours = n;
      sObj.shortfallHours = n;
    }
    if (s.shortfallSettings && typeof s.shortfallSettings === 'object') {
      sObj.shortfallSettings = JSON.parse(JSON.stringify(s.shortfallSettings));
    }
    if (s.floatMinutes != null && s.floatMinutes !== '') sObj.floatMinutes = s.floatMinutes;
    if (s.portalFloatMinutes != null && s.portalFloatMinutes !== '') sObj.portalFloatMinutes = s.portalFloatMinutes;
    await storePutSettingsDoc(cfg, gs.version || 0, sObj);
  } catch (e) {
    try { console.log(JSON.stringify({ event: 'sync_policy_settings_fail', message: String(e && e.message || e) })); } catch (e2) {}
  }
}

async function storeMergeSettingsIntoDataObj(cfg, obj) {
  if (!obj || typeof obj !== 'object') return obj;
  try {
    const sdoc = await storeGetSettingsDoc(cfg);
    if (!sdoc || typeof sdoc !== 'object') return obj;
    if (!obj.settings || typeof obj.settings !== 'object') obj.settings = {};
    // ادغام کلیدهای مهم از سند settings
    if (sdoc.leavePolicy && typeof sdoc.leavePolicy === 'object') {
      obj.settings.leavePolicy = sdoc.leavePolicy;
    }
    // سایر فیلدهای سیاست که فقط در settings هستند
    // سیاست‌های پایدار: سند settings همیشه مرجع است (حتی اگر data صفر/خالی شده باشد)
    if (sdoc.requestGraceDays != null && sdoc.requestGraceDays !== '') {
      obj.settings.requestGraceDays = sdoc.requestGraceDays;
    }
    if (sdoc.portalFloatMinutes != null && sdoc.portalFloatMinutes !== '') {
      obj.settings.portalFloatMinutes = sdoc.portalFloatMinutes;
    }
    if (sdoc.floatMinutes != null && sdoc.floatMinutes !== '') {
      obj.settings.floatMinutes = sdoc.floatMinutes;
    }
    ['currentYear', 'currentMonth', 'activeMonth'].forEach(function (k) {
      if (sdoc[k] != null && sdoc[k] !== '' && (obj.settings[k] == null || obj.settings[k] === '')) obj.settings[k] = sdoc[k];
    });
    if (sdoc.monthlyShortfallAllowanceHours != null && sdoc.monthlyShortfallAllowanceHours !== '') {
      obj.settings.monthlyShortfallAllowanceHours = sdoc.monthlyShortfallAllowanceHours;
      obj.settings.shortfallAllowanceHours = sdoc.monthlyShortfallAllowanceHours;
      obj.settings.shortfallHours = sdoc.monthlyShortfallAllowanceHours;
    } else if (sdoc.shortfallAllowanceHours != null && sdoc.shortfallAllowanceHours !== '') {
      obj.settings.monthlyShortfallAllowanceHours = sdoc.shortfallAllowanceHours;
      obj.settings.shortfallAllowanceHours = sdoc.shortfallAllowanceHours;
      obj.settings.shortfallHours = sdoc.shortfallAllowanceHours;
    }
    if (sdoc.shortfallSettings && typeof sdoc.shortfallSettings === 'object') {
      // ادغام byGroup: کلیدهای settings را نگه دار
      if (!obj.settings.shortfallSettings || typeof obj.settings.shortfallSettings !== 'object') {
        obj.settings.shortfallSettings = sdoc.shortfallSettings;
      } else {
        var ss = obj.settings.shortfallSettings;
        if (sdoc.shortfallSettings.allowanceHours != null && sdoc.shortfallSettings.allowanceHours !== '') {
          ss.allowanceHours = sdoc.shortfallSettings.allowanceHours;
        }
        if (sdoc.shortfallSettings.byGroup && typeof sdoc.shortfallSettings.byGroup === 'object') {
          if (!ss.byGroup || typeof ss.byGroup !== 'object') ss.byGroup = {};
          Object.keys(sdoc.shortfallSettings.byGroup).forEach(function (gk) {
            if (ss.byGroup[gk] == null || ss.byGroup[gk] === '') ss.byGroup[gk] = sdoc.shortfallSettings.byGroup[gk];
          });
        }
      }
    }
    // leavePolicy: همیشه از settings اگر وجود دارد (مرجع پایدار)
    if (sdoc.leavePolicy && typeof sdoc.leavePolicy === 'object') {
      if (!obj.settings.leavePolicy || typeof obj.settings.leavePolicy !== 'object') {
        obj.settings.leavePolicy = sdoc.leavePolicy;
      } else {
        var lpD = obj.settings.leavePolicy;
        var lpS = sdoc.leavePolicy;
        if (lpS.annualDays != null) lpD.annualDays = lpS.annualDays;
        if (lpS.carryMax != null) lpD.carryMax = lpS.carryMax;
        if (lpS.byContractType && typeof lpS.byContractType === 'object') {
          if (!lpD.byContractType) lpD.byContractType = {};
          Object.keys(lpS.byContractType).forEach(function (ck) {
            if (lpD.byContractType[ck] == null || lpD.byContractType[ck] === '') {
              lpD.byContractType[ck] = lpS.byContractType[ck];
            }
          });
        }
        if (lpS.byGroup && typeof lpS.byGroup === 'object') {
          if (!lpD.byGroup) lpD.byGroup = {};
          Object.keys(lpS.byGroup).forEach(function (gk) {
            // اگر data خالی است از settings بگیر؛ اگر هر دو دارند settings مرجع پایدار
            if (lpD.byGroup[gk] == null || lpD.byGroup[gk] === '') {
              lpD.byGroup[gk] = lpS.byGroup[gk];
            }
          });
          // اگر byGroup در data کاملاً خالی بود، کل را از settings بگیر
          if (Object.keys(lpD.byGroup).length === 0 && Object.keys(lpS.byGroup).length > 0) {
            lpD.byGroup = JSON.parse(JSON.stringify(lpS.byGroup));
          }
        }
      }
    }
  } catch (eM) {}
  return obj;
}

/** ثابت‌های ماهانه فقط با حذف صریح (tombstone) پاک می‌شوند؛ ذخیرهٔ ناقص یک کلاینت قدیمی آن‌ها را نمی‌برد */
function protectMonthlyVarsOnPut(prev, inc) {
  if (!prev || typeof prev !== 'object' || !inc || typeof inc !== 'object') return inc;
  const tomb = {};
  [].concat(Array.isArray(prev.monthlyVarsDeleted) ? prev.monthlyVarsDeleted : [],
            Array.isArray(inc.monthlyVarsDeleted) ? inc.monthlyVarsDeleted : []).forEach(function (id) { if (id) tomb[String(id)] = true; });
  const prevList = Array.isArray(prev.monthlyVars) ? prev.monthlyVars : [];
  const curList = Array.isArray(inc.monthlyVars) ? inc.monthlyVars : [];
  const byId = {};
  const order = [];
  prevList.concat(curList).forEach(function (v) {
    if (!v || !v.id) return;
    const id = String(v.id);
    if (tomb[id]) return;
    if (!byId[id]) order.push(id);
    byId[id] = v; // نسخهٔ کلاینت (آخرین ویرایش) مقدم است
  });
  curList.forEach(function (v) { // آیتم بدون id را هم نگه دار
    if (v && !v.id) { const k = 'noid:' + String(v.name || ''); if (!byId[k]) { order.push(k); byId[k] = v; } }
  });
  if (order.length || prevList.length || curList.length) inc.monthlyVars = order.map(function (k) { return byId[k]; });
  inc.monthlyVarsDeleted = Object.keys(tomb);
  return inc;
}

