    if (gd.fail) return storeFailResponse(gd.fail);
    if (!gd.obj) return jsonResponse({ ok: false, error: 'no_data' }, 404);
    if (!gd.obj.dailyAttendance) gd.obj.dailyAttendance = {};
    let savedDays = 0, savedPairs = 0;
    const unknownCodes = {};
