  if (!now.m) { try { var _pcN = (typeof getPortalCalendarNow === 'function') ? getPortalCalendarNow({ settings: st }) : null; if (_pcN && _pcN.realMonth) now.m = _pcN.realMonth; if (_pcN && _pcN.realYear) now.y = _pcN.realYear; } catch(eN){} }
